/** Messages metadata contains only IDs generated by the proxy ledger wrapper. */
export function upstreamMessagesRequestIdHeaders(_upstream: Headers): Record<string, string> { return {}; }

/** Preserve the newly constructed response and its lifecycle markers. */
export function retainUpstreamMessagesRequestId(response: Response, _upstream: Headers): Response {
  response.headers.delete("request-id");
  return response;
}
